/* Carry correct outcomes forward; every retry contains only the remaining mistakes. */
(()=>{
 function prepare(questions,stored={},progress={}){
  const baseline={};for(const q of questions){const saved=stored?.answers?.[q.id];baseline[q.id]=saved===1||saved===0?saved:progress[q.id]?.correct===true?1:0}
  return {baseline,questions:questions.filter(q=>baseline[q.id]!==1)};
 }
 function merge(questions,baseline,answers){return Object.fromEntries(questions.filter(q=>Object.hasOwn(answers,q.id)||Object.hasOwn(baseline,q.id)).map(q=>[q.id,Object.hasOwn(answers,q.id)?answers[q.id]:baseline[q.id]]))}
 function continueChapter(chapters,questions,scores,progress,last=null){
  const passed=index=>{const qs=questions.filter(q=>q.chapter===(chapters[index]?.id??index)),score=scores[qs[0]?.id];return score?.passed&&score.total===qs.length};
  if(Number.isInteger(last)&&chapters[last]&&!passed(last))return last;
  const started=chapters.findIndex((_,index)=>!passed(index)&&questions.some(q=>q.chapter===(chapters[index]?.id??index)&&progress[q.id]?.done));
  if(started>=0)return started;
  const next=chapters.findIndex((_,index)=>!passed(index));
  return next>=0?next:Number.isInteger(last)&&chapters[last]?last:0;
 }
 function lastChapterIndex(chapters,saved={}){const id=saved.id??saved.index;const index=chapters.findIndex(ch=>ch.id===id);return index>=0?index:null}
 window.RefinePractice={prepare,merge,continueChapter,lastChapterIndex};
})();

